using Xunit;

public class SymptomTest
{
    [Fact]
    public void TC_001_AddNewSymptom()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptom = new Symptom { Name = "Cough", Description = "Dry cough" };

        // Act
        symptomService.AddSymptom(symptom);

        // Assert
        Assert.Contains(symptom, symptomService.GetSymptoms());
    }

    [Fact]
    public void TC_002_ViewAndUpdateSymptom()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptom = new Symptom { Name = "Cough", Description = "Dry cough" };
        symptomService.AddSymptom(symptom);

        // Act
        symptom.Description = "Dry cough with phlegm";
        symptomService.UpdateSymptom(symptom);

        // Assert
        var updatedSymptom = symptomService.GetSymptomByName("Cough");
        Assert.Equal("Dry cough with phlegm", updatedSymptom.Description);
    }

    [Fact]
    public void TC_003_DeleteSymptom()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptom = new Symptom { Name = "Cough", Description = "Dry cough" };
        symptomService.AddSymptom(symptom);

        // Act
        symptomService.DeleteSymptom(symptom);

        // Assert
        Assert.DoesNotContain(symptom, symptomService.GetSymptoms());
    }

    [Fact]
    public void TC_004_DeleteSymptomWithConsultationRequest()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptom = new Symptom { Name = "Cough", Description = "Dry cough" };
        symptomService.AddSymptom(symptom);

        var consultationService = new ConsultationService();
        var consultation = new Consultation { Symptom = symptom };
        consultationService.AddConsultation(consultation);

        // Act & Assert
        Assert.Throws<InvalidOperationException>(() => symptomService.DeleteSymptom(symptom));
    }
}
